#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

const file = () => path.join(process.cwd(), 'todos.json');

function load() {
  try {
    const data = JSON.parse(fs.readFileSync(file(), 'utf8'));
    return Array.isArray(data) ? data : [];
  } catch (e) {
    return [];
  }
}

function save(todos) {
  fs.writeFileSync(file(), JSON.stringify(todos, null, 2));
}

function parseId(arg) {
  if (arg === undefined) return { error: 'Missing todo id.' };
  if (!/^\d+$/.test(arg)) return { error: `Invalid id: ${arg}` };
  return { id: Number(arg) };
}

function run(args) {
  const [cmd, ...rest] = args;
  const todos = load();

  switch (cmd) {
    case 'add': {
      const text = rest.join(' ').trim();
      if (!text) return { code: 1, err: 'Missing todo text. Usage: add "text"' };
      const id = todos.reduce((m, t) => Math.max(m, t.id), 0) + 1;
      todos.push({ id, text, completed: false, createdAt: new Date().toISOString() });
      save(todos);
      return { code: 0, out: `Added todo ${id}: ${text}` };
    }
    case 'list': {
      if (!todos.length) return { code: 0, out: 'No todos found.' };
      return {
        code: 0,
        out: todos.map((t) => `${t.id} [${t.completed ? 'x' : ' '}] ${t.text}`).join('\n'),
      };
    }
    case 'complete':
    case 'delete': {
      const p = parseId(rest[0]);
      if (p.error) return { code: 1, err: p.error };
      const idx = todos.findIndex((t) => t.id === p.id);
      if (idx === -1) return { code: 1, err: `Todo ${p.id} not found.` };
      if (cmd === 'complete') {
        todos[idx].completed = true;
        save(todos);
        return { code: 0, out: `Completed todo ${p.id}` };
      }
      todos.splice(idx, 1);
      save(todos);
      return { code: 0, out: `Deleted todo ${p.id}` };
    }
    default:
      return {
        code: 1,
        err: cmd
          ? `Unknown command: ${cmd}\nUsage: add|list|complete|delete`
          : 'Usage: node index.js <add|list|complete|delete> [args]',
      };
  }
}

if (require.main === module) {
  const r = run(process.argv.slice(2));
  if (r.out) console.log(r.out);
  if (r.err) console.error(r.err);
  process.exit(r.code);
}

module.exports = { run };
